export function bookFrontmatter(id){const book=books[id];let note='';try{note=localStorage.getItem('wortreise-margin-'+id)||'';}catch{}return `<div class="book-opening"><div class="book-imprint"><span class="book-number">Nº ${book.number}</span><span>${book.label}</span></div><div class="book-title-row"><div class="book-name"><span>wortreise /</span><h2>${book.title}</h2><p>${book.scribble}</p></div><label class="book-memo"><span>note to myself <i>↙</i></span><textarea data-book-note="${id}" aria-label="Your personal note in ${esc(book.title)}" maxlength="500" placeholder="${esc(book.note)}">${esc(note)}</textarea><small data-note-status="${id}">${note?'Saved on this device':'Just for you. On this device.'}</small></label></div><div class="book-doodle" aria-hidden="true"><svg viewBox="0 0 108 70" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${doodles[id]}"/></svg></div><span class="book-scrap scrap-one" aria-hidden="true">${book.scraps[0]}</span><span class="book-scrap scrap-two" aria-hidden="true">${book.scraps[1]}</span><span class="margin-scribble" aria-hidden="true">${book.scraps[2]}</span><div class="binding" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></div></div>`;}
export function selectBook(id){if(!books[id])return;const previous=document.documentElement.dataset.book;document.documentElement.dataset.book=id;const name=document.querySelector('[data-current-book]');if(name)name.textContent=books[id].title;if(previous&&previous!==id)swapBooks(previous,id);}
let swapLayer;
const covers={home:'#806344',learn:'#49666b',exam:'#8b4440',sounds:'#a76449',practice:'#5d6940',translate:'#3b556e',captions:'#49434c'};
function swapBooks(previous,next){swapLayer?.remove();if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const old=books[previous],book=books[next];if(!old)return;const layer=document.createElement('div');swapLayer=layer;layer.className='book-transition';layer.setAttribute('aria-hidden','true');const cover=(id,data)=>`<div class="swap-pages"></div><div class="swap-cover" style="--swap-colour:${covers[id]}"><span>WORTREISE</span><strong>${id==='exam'?'Semester revision':data.title}</strong><small>Nº ${data.number} · DEUTSCH</small><i></i></div>`;layer.innerHTML=`<div class="swap-shadow"></div><div class="swap-book swap-out">${cover(previous,old)}</div><div class="swap-book swap-in">${cover(next,book)}</div>`;document.body.append(layer);layer.addEventListener('animationend',event=>{if(event.target===layer)layer.remove();});setTimeout(()=>layer.remove(),1200);}
export function mountBooks(){document.addEventListener('input',event=>{const id=event.target.dataset.bookNote;if(!books[id])return;const status=document.querySelector(`[data-note-status="${id}"]`);try{localStorage.setItem('wortreise-margin-'+id,event.target.value);status.textContent='Saved on this device';}catch{status.textContent='Couldn’t save here. Copy your note before leaving.';}});}
